float r=150.;

vec2 rel(vec2 a, vec2 b){
vec2 c = b;
if(a.x-b.x>R.x/2.){c.x=b.x+R.x;}
if(a.x-b.x<-R.x/2.){c.x=b.x-R.x;}
if(a.y-b.y>R.y/2.){c.y=b.y+R.y;}
if(a.y-b.y<-R.y/2.){c.y=b.y-R.y;}
return c;
}

float ang(float a, float b){
if(b-a>3.14){return b-a-6.28;}
if(b-a<-3.14){return b-a+6.28;}
return b-a;
}

float dirTo(vec2 a, vec2 b){
return atan((b.y-a.y),(b.x-a.x));
}

//random hash from Dave_Hoskins https://www.shadertoy.com/view/4djSRW
vec3 hash33(vec3 p3){
p3 = fract(p3 * vec3(.1031, .1030, .0973));
p3 += dot(p3, p3.yxz+33.33);
return fract((p3.xxy + p3.yxx)*p3.zyx);
}

go{
O=vec4(0.);
if(I.x>n){return;}
if(I.y>1.){return;}
if(iFrame<1 || tex(C1,ivec2(32,1)).x!=0.){
O.xyz=hash33(vec3(I,iDate[3]));
O.x*=R.x;
O.y*=R.y;
O.z=6.28;
if(I.x>n/3.){if(I.x>2.*n/3.){O.w=2.;return;}O.w=1.;return;}
return;}

float fC,fA,nC,nA=0.;
vec2 cM=vec2(0.);
vec4 me=tex(C0,ivec2(I));
O.w=me.w;

for(float i=0.;i<n;i++){
vec4 them=tex(C0,ivec2(i,0.));
them.xy=rel(me.xy,them.xy);
float d=distance(me.xy,them.xy);
if(d<=0.||d>r){continue;}
if(d<10.){
if(mod(them.w-me.w,3.)==1.){O.w=them.w;}
}
if(mod(them.w-me.w,3.)!=1.){
fC++;
fA+=ang(me.z,them.z);
cM+=them.xy;}
if(d>.25*r){continue;}
if(mod(them.w-me.w,3.)==2.){continue;}
nC++;
nA+=ang(me.z,dirTo(them.xy, me.xy));
}

if(fC>0.){
me.z+=.0005*fA/fC;
me.z+=.015*ang(me.z,dirTo(me.xy,cM/fC));
if(nC>0.){me.z+=.03*nA/nC;}
}

if(M.z>0.&&distance(me.xy,M.xy)<150.){me.z-=.1*ang(me.z,dirTo(me.xy,M.xy));}

O.z=mod(me.z,6.28);
O.xy=vec2(mod(me.x+2.*cos(me.z),R.x),mod(me.y+2.*sin(me.z),R.y));
}
